<?php
require_once __DIR__.'/../app/bootstrap.php';
$page = $_GET['page'] ?? (user() ? 'dashboard' : 'login');
if ($page === 'logout') { session_destroy(); redirect('?page=login'); }
if ($page === 'login' && $_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $s=$pdo->prepare('SELECT * FROM users WHERE email=? AND is_active=1 LIMIT 1'); $s->execute([trim($_POST['email']??'')]); $u=$s->fetch();
 if ($u && password_verify($_POST['password']??'', $u['password_hash'])) { session_regenerate_id(true); $_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']]; redirect('?page=dashboard'); }
 $loginError='Invalid email or password.';
}
if ($page==='setup' && $_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf();
 $count=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
 if ($count>0) { $setupError='Setup has already been completed.'; }
 else {
  $names=['Admin'];
  $emails=[trim($_POST['admin_email']??'')];
  $password=$_POST['password']??'';
  if (!filter_var($emails[0],FILTER_VALIDATE_EMAIL) || strlen($password)<12) $setupError='Enter a valid admin email and a password of at least 12 characters.';
  else {
   $pdo->beginTransaction(); $q=$pdo->prepare('INSERT INTO users(name,email,password_hash,role,must_change_password) VALUES(?,?,?,?,0)');
   $q->execute([$names[0],$emails[0],password_hash($password,PASSWORD_DEFAULT),'admin']);
   $pdo->commit(); flash('Admin account created. Add your four sales users and projects from Settings.'); redirect('?page=login');
  }
 }
}
if ($page!=='login' && $page!=='setup') require_login();

if ($page==='lead-save' && $_SERVER['REQUEST_METHOD']==='POST') {
 require_login(); verify_csrf();
 $id=(int)($_POST['id']??0); $projectId=(int)($_POST['project_id']??0); $name=trim($_POST['full_name']??''); $phone=preg_replace('/[^0-9+]/','',$_POST['phone']??'');
 if ($name==='' || strlen($phone)<8) { flash('Name and a valid phone number are required.','error'); redirect('?page=leads'); }
 $projectId=$projectId ?: null; $owner=$projectId ? project_owner($pdo,$projectId) : null; if (is_admin() && !empty($_POST['assigned_to'])) { $owner=(int)$_POST['assigned_to']; }
 if ($id) {
  $old=$pdo->prepare('SELECT project_id,assigned_to FROM leads WHERE id=?'); $old->execute([$id]); $oldLead=$old->fetch();
  if (!is_admin()) { $projectId=$oldLead['project_id'] ? (int)$oldLead['project_id'] : null; $assigned=$oldLead['assigned_to'] ? (int)$oldLead['assigned_to'] : null; } else { $assigned=$owner; }
  $q=$pdo->prepare('UPDATE leads SET full_name=?,phone=?,email=?,project_id=?,assigned_to=?,campaign_name=?,adset_name=?,ad_name=?,budget=?,preferred_location=?,property_type=?,purpose=?,status=?,next_followup_at=?,lost_reason=?,remarks=? WHERE id=?');
  $q->execute([$name,$phone,trim($_POST['email']??'')?:null,$projectId,$assigned,trim($_POST['campaign_name']??'')?:null,trim($_POST['adset_name']??'')?:null,trim($_POST['ad_name']??'')?:null,trim($_POST['budget']??'')?:null,trim($_POST['preferred_location']??'')?:null,trim($_POST['property_type']??'')?:null,trim($_POST['purpose']??'')?:null,$_POST['status']??'New',($_POST['next_followup_at']??'')?:null,trim($_POST['lost_reason']??'')?:null,trim($_POST['remarks']??'')?:null,$id]);
  log_activity($pdo,$id,'Lead updated',trim($_POST['remarks']??''));
 } else {
  $code='RE'.date('ym').strtoupper(bin2hex(random_bytes(3)));
  $q=$pdo->prepare('INSERT INTO leads(lead_code,full_name,phone,email,project_id,assigned_to,source,campaign_name,adset_name,ad_name,budget,preferred_location,property_type,purpose,status,next_followup_at,remarks,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
  $q->execute([$code,$name,$phone,trim($_POST['email']??'')?:null,$projectId,$owner,$_POST['source']??'Manual',trim($_POST['campaign_name']??'')?:null,trim($_POST['adset_name']??'')?:null,trim($_POST['ad_name']??'')?:null,trim($_POST['budget']??'')?:null,trim($_POST['preferred_location']??'')?:null,trim($_POST['property_type']??'')?:null,trim($_POST['purpose']??'')?:null,$_POST['status']??'New',($_POST['next_followup_at']??'')?:null,trim($_POST['remarks']??'')?:null,user()['id']]);
  $id=(int)$pdo->lastInsertId(); log_activity($pdo,$id,'Lead created','Created via CRM');
 }
 flash('Lead saved successfully.'); redirect('?page=leads');
}
if ($page==='project-save' && $_SERVER['REQUEST_METHOD']==='POST') {
 require_login(); if(!is_admin()) {http_response_code(403);exit('Forbidden');} verify_csrf();
 $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $owner=(int)($_POST['owner_user_id']??0) ?: null;
 if($name!=='') { if($id){$q=$pdo->prepare('UPDATE projects SET name=?,location=?,property_type=?,owner_user_id=?,is_active=? WHERE id=?');$q->execute([$name,trim($_POST['location']??''),trim($_POST['property_type']??''),$owner,isset($_POST['is_active'])?1:0,$id]);}else{$q=$pdo->prepare('INSERT INTO projects(name,location,property_type,owner_user_id) VALUES(?,?,?,?)');$q->execute([$name,trim($_POST['location']??''),trim($_POST['property_type']??''),$owner]);} flash('Project saved.'); }
 redirect('?page=settings');
}
if ($page==='user-save' && $_SERVER['REQUEST_METHOD']==='POST') {
 require_login(); if(!is_admin()) {http_response_code(403);exit('Forbidden');} verify_csrf();
 $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $pass=$_POST['password']??'';
 if($name && filter_var($email,FILTER_VALIDATE_EMAIL)) { if($id){ if($pass!==''){$q=$pdo->prepare('UPDATE users SET name=?,email=?,password_hash=? WHERE id=?');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$id]);}else{$q=$pdo->prepare('UPDATE users SET name=?,email=? WHERE id=?');$q->execute([$name,$email,$id]);}}else{if(strlen($pass)<12){flash('New user password must be at least 12 characters.','error');redirect('?page=settings');}$q=$pdo->prepare('INSERT INTO users(name,email,password_hash,role,must_change_password) VALUES(?,?,?,\'sales\',0)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);} flash('User saved.'); }
 redirect('?page=settings');
}

$flash=take_flash();
function header_html(string $title, ?array $flash): void { ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · Estate CRM</title><link rel="stylesheet" href="assets/style.css"></head><body><?php if(user()): ?><aside class="sidebar"><div class="brand"><span class="brandmark">E</span><div><b>Estate CRM</b><small>Sales workspace</small></div></div><nav><a href="?page=dashboard">▦ Dashboard</a><a href="?page=leads">◎ All Leads</a><a href="?page=leads&new=1">＋ Add Lead</a><a href="?page=followups">◷ Follow-ups</a><?php if(is_admin()): ?><a href="?page=settings">⚙ Settings</a><?php endif; ?></nav><div class="sidebottom"><div class="userchip"><span class="avatar"><?=e(strtoupper(substr(user()['name'],0,1)))?></span><div><b><?=e(user()['name'])?></b><small><?=e(ucfirst(user()['role']))?></small></div></div><a href="?page=logout">↪ Sign out</a></div></aside><?php endif; ?><main class="main <?=user()?'withside':''?>"><header class="topbar"><div><span class="eyebrow">REAL ESTATE SALES</span><h1><?=e($title)?></h1></div><?php if(user()): ?><a class="btn primary" href="?page=leads&new=1">＋ Add lead</a><?php endif; ?></header><?php if($flash): ?><div class="notice <?=e($flash['type'])?>"><?=e($flash['msg'])?></div><?php endif; ?><?php }
function footer_html(): void { ?></main><script>document.querySelectorAll('[data-confirm]').forEach(el=>el.addEventListener('click',e=>{if(!confirm(el.dataset.confirm))e.preventDefault()}));</script></body></html><?php }

if($page==='login') { header_html('Sign in',$flash); ?><section class="authwrap"><form method="post" class="panel auth"><div class="brandmark big">E</div><h2>Welcome back</h2><p class="muted">Sign in to manage your property enquiries.</p><?php if(!empty($loginError)): ?><div class="notice error"><?=e($loginError)?></div><?php endif; ?><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Email address<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary full">Sign in</button></form></section><?php footer_html(); exit; }
