if($page==='dashboard') {
 $total=(int)$pdo->query('SELECT COUNT(*) FROM leads')->fetchColumn(); $today=(int)$pdo->query('SELECT COUNT(*) FROM leads WHERE DATE(created_at)=CURDATE()')->fetchColumn(); $due=(int)$pdo->query('SELECT COUNT(*) FROM leads WHERE next_followup_at IS NOT NULL AND next_followup_at<=NOW() AND status NOT IN (\'Booking Confirmed\',\'Lost / Not Interested\')')->fetchColumn(); $visits=(int)$pdo->query("SELECT COUNT(*) FROM leads WHERE status IN ('Site Visit Scheduled','Site Visit Completed')")->fetchColumn();
 $byStatus=$pdo->query('SELECT status,COUNT(*) total FROM leads GROUP BY status ORDER BY total DESC')->fetchAll(); $byOwner=$pdo->query("SELECT u.name,COUNT(l.id) total,SUM(l.status='Booking Confirmed') bookings FROM users u LEFT JOIN leads l ON l.assigned_to=u.id WHERE u.role='sales' AND u.is_active=1 GROUP BY u.id ORDER BY total DESC")->fetchAll();
 header_html('Dashboard',$flash); ?><div class="stats"><div class="stat"><span>Total leads</span><b><?=number_format($total)?></b><small>All time</small></div><div class="stat"><span>New today</span><b><?=number_format($today)?></b><small>Created today</small></div><div class="stat warn"><span>Follow-ups due</span><b><?=number_format($due)?></b><small>Due now or overdue</small></div><div class="stat"><span>Site visits</span><b><?=number_format($visits)?></b><small>Scheduled + completed</small></div></div><div class="grid2"><section class="panel"><div class="panelhead"><div><h2>Lead pipeline</h2><p class="muted">Current lead status distribution</p></div><a href="?page=leads">View all →</a></div><?php if(!$byStatus): ?><p class="empty">No leads yet. Add a project, then create your first lead.</p><?php else: foreach($byStatus as $r): ?><div class="barrow"><span><?=e($r['status'])?></span><b><?=number_format($r['total'])?></b></div><?php endforeach; endif; ?></section><section class="panel"><div class="panelhead"><div><h2>Team overview</h2><p class="muted">Leads assigned by project owner</p></div></div><div class="tablewrap"><table><thead><tr><th>Executive</th><th>Leads</th><th>Bookings</th></tr></thead><tbody><?php foreach($byOwner as $r): ?><tr><td><?=e($r['name'])?></td><td><?=number_format((int)$r['total'])?></td><td><?=number_format((int)$r['bookings'])?></td></tr><?php endforeach; ?></tbody></table></div></section></div><section class="panel"><div class="panelhead"><div><h2>Recent leads</h2><p class="muted">Latest enquiries across all projects</p></div><a href="?page=leads">Open lead manager →</a></div><?php $recent=$pdo->query('SELECT l.*,p.name project,u.name owner FROM leads l LEFT JOIN projects p ON p.id=l.project_id LEFT JOIN users u ON u.id=l.assigned_to ORDER BY l.created_at DESC LIMIT 8')->fetchAll(); ?><div class="tablewrap"><table><thead><tr><th>Lead</th><th>Project</th><th>Owner</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><a href="?page=lead&id=<?=$r['id']?>"><b><?=e($r['full_name'])?></b></a><small><?=e($r['phone'])?></small></td><td><?=e($r['project']??'Unassigned')?></td><td><?=e($r['owner']??'Unassigned')?></td><td><span class="badge <?=badge_class($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td></tr><?php endforeach; ?></tbody></table></div></section><?php footer_html(); exit;
}
if($page==='leads') {
 $q=trim($_GET['q']??''); $status=trim($_GET['status']??''); $project=(int)($_GET['project']??0);
 $sql='SELECT l.*,p.name project,u.name owner FROM leads l LEFT JOIN projects p ON p.id=l.project_id LEFT JOIN users u ON u.id=l.assigned_to WHERE 1=1'; $args=[];
 if($q!==''){$sql.=' AND (l.full_name LIKE ? OR l.phone LIKE ? OR l.lead_code LIKE ?)';array_push($args,"%$q%","%$q%","%$q%");} if($status!==''){$sql.=' AND l.status=?';$args[]=$status;} if($project){$sql.=' AND l.project_id=?';$args[]=$project;} $sql.=' ORDER BY l.created_at DESC LIMIT 300'; $st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll(); $projects=$pdo->query('SELECT id,name FROM projects WHERE is_active=1 ORDER BY name')->fetchAll();
 header_html('All leads',$flash); ?><section class="panel"><form class="filters" method="get"><input type="hidden" name="page" value="leads"><input name="q" placeholder="Search name, phone or lead ID" value="<?=e($q)?>"><select name="project"><option value="0">All projects</option><?php foreach($projects as $p): ?><option value="<?=$p['id']?>" <?=$project===$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach; ?></select><select name="status"><option value="">All statuses</option><?php foreach(status_options() as $s): ?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select><button class="btn secondary">Filter</button></form><div class="panelhead"><div><h2><?=count($rows)?> leads shown</h2><p class="muted">Maximum 300 latest records per view</p></div><a class="btn primary" href="?page=leads&new=1">＋ Add lead</a></div><div class="tablewrap"><table><thead><tr><th>Lead</th><th>Project</th><th>Assigned to</th><th>Source</th><th>Status</th><th>Next follow-up</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="?page=lead&id=<?=$r['id']?>"><b><?=e($r['full_name'])?></b></a><small><?=e($r['lead_code'])?> · <?=e($r['phone'])?></small></td><td><?=e($r['project']??'—')?></td><td><?=e($r['owner']??'Unassigned')?></td><td><?=e($r['source'])?></td><td><span class="badge <?=badge_class($r['status'])?>"><?=e($r['status'])?></span></td><td><?= $r['next_followup_at'] ? e(date('d M, h:i A',strtotime($r['next_followup_at']))) : '—' ?></td><td><a href="?page=lead&id=<?=$r['id']?>">Open →</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7" class="empty">No leads match these filters.</td></tr><?php endif; ?></tbody></table></div></section><?php if(isset($_GET['new'])): render_lead_form($pdo,null); endif; footer_html(); exit;
}
if($page==='lead') { $id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT l.*,p.name project,u.name owner FROM leads l LEFT JOIN projects p ON p.id=l.project_id LEFT JOIN users u ON u.id=l.assigned_to WHERE l.id=?');$s->execute([$id]);$lead=$s->fetch();if(!$lead){flash('Lead not found.','error');redirect('?page=leads');}$acts=$pdo->prepare('SELECT a.*,u.name FROM activities a LEFT JOIN users u ON u.id=a.user_id WHERE a.lead_id=? ORDER BY a.created_at DESC');$acts->execute([$id]);$activities=$acts->fetchAll();header_html('Lead details',$flash); ?><section class="panel"><div class="leadhero"><div><span class="eyebrow"><?=e($lead['lead_code'])?></span><h2><?=e($lead['full_name'])?></h2><p class="muted"><?=e($lead['phone'])?> · <?=e($lead['email']??'No email')?></p></div><span class="badge <?=badge_class($lead['status'])?>"><?=e($lead['status'])?></span></div><div class="detailgrid"><div><small>Project</small><b><?=e($lead['project']??'Unassigned')?></b></div><div><small>Assigned to</small><b><?=e($lead['owner']??'Unassigned')?></b></div><div><small>Source</small><b><?=e($lead['source'])?></b></div><div><small>Budget</small><b><?=e($lead['budget']??'—')?></b></div><div><small>Location</small><b><?=e($lead['preferred_location']??'—')?></b></div><div><small>Next follow-up</small><b><?=e($lead['next_followup_at']?date('d M Y, h:i A',strtotime($lead['next_followup_at'])):'—')?></b></div></div><div class="actions"><a class="btn secondary" href="tel:<?=e($lead['phone'])?>">Call</a><a class="btn secondary" target="_blank" rel="noopener" href="https://wa.me/<?=e(preg_replace('/\D/','',$lead['phone']))?>">WhatsApp</a><a class="btn primary" href="?page=leads&edit=<?=$id?>">Edit lead</a></div></section><section class="panel"><h2>Activity history</h2><?php foreach($activities as $a): ?><div class="activity"><b><?=e($a['type'])?></b><p><?=e($a['note'])?></p><small><?=e($a['name']??'System')?> · <?=e(date('d M Y, h:i A',strtotime($a['created_at'])))?></small></div><?php endforeach; ?></section><?php if(isset($_GET['edit'])) render_lead_form($pdo,$lead); footer_html(); exit; }
if($page==='followups') { $rows=$pdo->query("SELECT l.*,p.name project,u.name owner FROM leads l LEFT JOIN projects p ON p.id=l.project_id LEFT JOIN users u ON u.id=l.assigned_to WHERE l.next_followup_at IS NOT NULL AND l.status NOT IN ('Booking Confirmed','Lost / Not Interested') ORDER BY l.next_followup_at ASC LIMIT 300")->fetchAll();header_html('Follow-ups',$flash); ?><section class="panel"><div class="panelhead"><div><h2>Upcoming and overdue follow-ups</h2><p class="muted">Sorted by earliest follow-up first</p></div></div><div class="tablewrap"><table><thead><tr><th>Lead</th><th>Project</th><th>Owner</th><th>Follow-up date</th><th>Timing</th></tr></thead><tbody><?php foreach($rows as $r):$past=strtotime($r['next_followup_at'])<time(); ?><tr><td><a href="?page=lead&id=<?=$r['id']?>"><b><?=e($r['full_name'])?></b></a><small><?=e($r['phone'])?></small></td><td><?=e($r['project']??'—')?></td><td><?=e($r['owner']??'Unassigned')?></td><td><?=e(date('d M Y, h:i A',strtotime($r['next_followup_at'])))?></td><td><span class="badge <?=$past?'red':'green'?>"><?=$past?'Overdue':'Upcoming'?></span></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5" class="empty">No follow-ups scheduled.</td></tr><?php endif; ?></tbody></table></div></section><?php footer_html(); exit; }
if($page==='settings') { if(!is_admin()){http_response_code(403);exit('Forbidden');}$users=$pdo->query("SELECT id,name,email,role,is_active FROM users ORDER BY role DESC,name")->fetchAll();$projects=$pdo->query('SELECT p.*,u.name owner FROM projects p LEFT JOIN users u ON u.id=p.owner_user_id ORDER BY p.name')->fetchAll();$sales=array_filter($users,fn($u)=>$u['role']==='sales');header_html('Settings',$flash); ?><div class="grid2"><section class="panel"><h2>Projects & assignment</h2><p class="muted">Each project's owner receives its new leads automatically.</p><form method="post" action="?page=project-save" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Project name<input name="name" required placeholder="e.g. Premium Residences - Baner"></label><label>Location<input name="location" placeholder="Baner, Pune"></label><label>Property type<input name="property_type" placeholder="Residential / Commercial / Plot"></label><label>Assigned executive<select name="owner_user_id"><option value="0">Unassigned</option><?php foreach($sales as $u): ?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach; ?></select></label><button class="btn primary">Add project</button></form><div class="tablewrap"><table><thead><tr><th>Project</th><th>Owner</th><th>Update owner</th></tr></thead><tbody><?php foreach($projects as $p): ?><tr><td><?=e($p['name'])?><small><?=e($p['location'])?></small></td><td><?=e($p['owner']??'Unassigned')?></td><td><form method="post" action="?page=project-save" class="inlineform"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="name" value="<?=e($p['name'])?>"><input type="hidden" name="location" value="<?=e($p['location'])?>"><input type="hidden" name="property_type" value="<?=e($p['property_type'])?>"><input type="hidden" name="is_active" value="<?=$p['is_active']?>"><select name="owner_user_id"><option value="0">Unassigned</option><?php foreach($sales as $u): ?><option value="<?=$u['id']?>" <?=((int)$p['owner_user_id']===(int)$u['id'])?'selected':''?>><?=e($u['name'])?></option><?php endforeach; ?></select><button class="btn secondary">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><h2>Sales team accounts</h2><p class="muted">Create team logins. Set a unique strong password for each salesperson.</p><form method="post" action="?page=user-save" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Temporary password (12+ chars)<input type="password" name="password" minlength="12" required></label><button class="btn primary">Add salesperson</button></form><div class="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td></tr><?php endforeach; ?></tbody></table></div></section></div><section class="panel"><h2>Integration endpoints</h2><p class="muted">Use the secure webhook endpoint for n8n, Make, or a server-side Meta Lead Ads connector. Keep the token private.</p><code><?=e(app_url($config))?>/api/webhook.php</code><p class="muted">See docs/INTEGRATIONS.md for payload format, Meta setup and website form integration.</p></section><?php footer_html(); exit; }

function render_lead_form(PDO $pdo, ?array $lead): void { $projects=$pdo->query('SELECT id,name FROM projects WHERE is_active=1 ORDER BY name')->fetchAll(); ?><section class="panel leadform"><div class="panelhead"><div><h2><?=$lead?'Edit lead':'Add new lead'?></h2><p class="muted">New leads are assigned to the salesperson configured on the selected project.</p></div></div><form method="post" action="?page=lead-save" class="formgrid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($lead['id']??'')?>"><label>Customer name *<input name="full_name" required value="<?=e($lead['full_name']??'')?>"></label><label>Mobile number *<input name="phone" required value="<?=e($lead['phone']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($lead['email']??'')?>"></label><label>Project<select name="project_id"><option value="0">Select project</option><?php foreach($projects as $p): ?><option value="<?=$p['id']?>" <?=((int)($lead['project_id']??0)===(int)$p['id'])?'selected':''?>><?=e($p['name'])?></option><?php endforeach; ?></select></label><?php if(is_admin()): $salesUsers=$pdo->query("SELECT id,name FROM users WHERE role='sales' AND is_active=1 ORDER BY name")->fetchAll(); ?><label>Assigned salesperson<select name="assigned_to"><option value="0">Use project owner</option><?php foreach($salesUsers as $su): ?><option value="<?=$su['id']?>" <?=((int)($lead['assigned_to']??0)===(int)$su['id'])?'selected':''?>><?=e($su['name'])?></option><?php endforeach; ?></select></label><?php endif; ?><label>Lead source<select name="source"><?php foreach(['Meta Ads','Website','Manual','API'] as $s): ?><option <?=($lead['source']??'Manual')===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select></label><label>Budget<input name="budget" placeholder="e.g. ₹75 lakh" value="<?=e($lead['budget']??'')?>"></label><label>Preferred location<input name="preferred_location" value="<?=e($lead['preferred_location']??'')?>"></label><label>Property type<input name="property_type" placeholder="2 BHK / Office / Plot" value="<?=e($lead['property_type']??'')?>"></label><label>Purpose<select name="purpose"><option value="">Select</option><?php foreach(['Self use','Investment','Rental','Other'] as $s): ?><option <?=($lead['purpose']??'')===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select></label><label>Campaign name<input name="campaign_name" value="<?=e($lead['campaign_name']??'')?>"></label><label>Ad set name<input name="adset_name" value="<?=e($lead['adset_name']??'')?>"></label><label>Ad name<input name="ad_name" value="<?=e($lead['ad_name']??'')?>"></label><label>Status<select name="status"><?php foreach(status_options() as $s): ?><option <?=($lead['status']??'New')===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select></label><label>Next follow-up<input type="datetime-local" name="next_followup_at" value="<?=e(!empty($lead['next_followup_at'])?date('Y-m-d\TH:i',strtotime($lead['next_followup_at'])):'')?>"></label><label>Lost reason<input name="lost_reason" value="<?=e($lead['lost_reason']??'')?>"></label><label class="span2">Remarks / call notes<textarea name="remarks" rows="3"><?=e($lead['remarks']??'')?></textarea></label><div class="span2"><button class="btn primary">Save lead</button></div></form></section><?php }
